using System;using System.IO;using System.Collections.Generic;using System.Runtime.InteropServices;using System.Web.Script.Serialization;using interop.ICApiIronCAD;
namespace RockPro{public static class LatchInProcess{
public static int Run(string folder){var j=new JavaScriptSerializer();var r=new Dictionary<string,object>();IZDoc owned=null;bool ok=false;try{dynamic l=Marshal.GetActiveObject("IronCAD.Application");var b=(IZBaseApp)l.ZIronCADApp;if(!b.ApiVersion.StartsWith("25."))throw new Exception("Wrong host");owned=b.OpenNewDoc(eZDocType.Z_SCENE,false,true,"");var s=(IZSceneDoc)owned;var p=s.CreateProfile();double[][] pts={new[]{0.0,0.0},new[]{.1,0.0},new[]{.1,.05},new[]{0.0,.05}};for(int i=0;i<4;i++)p.CreateLine(pts[i],pts[(i+1)%4],i+1);var part=s.CreatePart();((IZElement)part).Name="RP_BINDING_PROBE";var f=((IZPartFeatureMgr)part).CreateExtrudeFeature(eZOperationType.Z_UNITE,false,.02,0,0,p,eZFeatureProfileRelType.Z_FEATURE_PROFILE_ABSORB);part.Update();s.Update();var par=s.ParameterMgr.CreateParameter(eZParamType.Z_PARAMETER_TYPE_LENGTH,"RP_Test",.04);
try{var box=(IZSizeBox)f;box.Reset(false);box.HeightExpression="Parent\\Parent\\Params\\RP_Test";((IZSceneElement)f).ForceSetupParameterExpression();r["size_expression"]="PASS";}catch(Exception e){r["size_expression"]=e.ToString();}
try{((IZSceneElement)part).set_PositionTransformComponentExpression((eZTransformComponentType)0,"Parent\\Params\\RP_Test");((IZSceneElement)part).ForceSetupParameterExpression();r["position_expression"]="PASS";}catch(Exception e){r["position_expression"]=e.ToString();}
((IZAssembly)s.GetTopElement()).RegenerateParts(true);s.Update();r["bounds"]=part.GetBody(true).GetBoundingBox();r["position"]=((IZSceneElement)part).GetTransformToParent().GetValue(3,0);s.SaveAs(Path.Combine(folder,"probe.ics"),eZLinksSaveOptions.Z_LINKS_COPY_ALL,false);ok=true;}catch(Exception e){r["error"]=e.ToString();}finally{if(owned!=null){try{owned.Close();}catch(Exception e){r["cleanup_error"]=e.ToString();ok=false;}}r["passed"]=ok;File.WriteAllText(Path.Combine(folder,"result.json"),j.Serialize(r));}return ok?0:1;}
}}

